"""
Fuehrt einen manuellen Renewal-Verschiebungslauf aus.

Fachliche Logik:
1. Basis-Abos mit Status 2 werden ueber die BestellId gruppiert.
2. Pro BestellId darf genau ein ServiceExpiry-Timestamp vorhanden sein.
3. Der ServiceExpiry muss exakt auf einem 10-Sekunden-Schritt liegen.
4. Der Zielzeitpunkt bleibt immer auf demselben Kalendertag.
5. Renewals am 22. eines Monats vor 08:00 Uhr duerfen nur in das Fenster
   08:00:00 bis vor 09:00:00 verschoben werden.
6. Alle anderen Renewals duerfen ueber den ganzen gleichen Tag verteilt werden.
7. Die Slot-Kapazitaet wird als kombinierte Last aus ExpiryDate- und
   StartDate-Updates berechnet.
8. Zwischen 06:00:00 und vor 18:00:00 gilt die Tageskapazitaet, ausserhalb
   davon die Nachtkapazitaet.
9. Freie Slots werden nach geringster zeitlicher Abweichung zum alten
   ServiceExpiry bevorzugt.
10. MOVED bedeutet nur, dass Datum oder Uhrzeit wirklich geaendert wurden.
11. Verknuepfte Abos mit Status 10 erhalten als neues StartDate den geplanten
    ServiceExpiry der Basisgruppe.
"""

import json
import logging
import time
from dataclasses import dataclass
from datetime import date, datetime, timedelta
from datetime import time as datetime_time

import pandas as pd
import requests

from ..config_service import get_esuite_api_config
from ..db.db_service import execute_sql_query
from ..utils.http_utils import retry_request
from ..utils.progress_logging import iter_with_progress

DAYTIME_MAX_PER_TIMESTAMP = 10
NIGHTTIME_MAX_PER_TIMESTAMP = 40
DAYTIME_START_TIME = datetime_time(6, 0, 0)
DAYTIME_END_TIME = datetime_time(18, 0, 0)
FULL_DAY_START_TIME = datetime_time(0, 0, 0)
FULL_DAY_END_TIME = datetime_time(0, 0, 0)
SPECIAL_DAY_OF_MONTH = 22
SPECIAL_SOURCE_END_TIME = datetime_time(8, 0, 0)
SPECIAL_TARGET_START_TIME = datetime_time(8, 0, 0)
SPECIAL_TARGET_END_TIME = datetime_time(9, 0, 0)
STEP_SECONDS = 10
API_DELAY_SECONDS = 0.5
LOCAL_TIMEZONE = "Europe/Berlin"

QUERY_SERVICE_EXPIRY = """
SELECT
sub.SubscriptionId as subscriptionid,
sub.ServiceExpiry as serviceexpiry,
sub.BestellId as bestellid,
substr(sub.payer,-9) as accountid
FROM dbm_lesermarkt.tb_subscriptionsreport_shortened sub
WHERE sub.SubscriptionStatusID = 2
AND sub.subscribedprice > 0
AND sub.BestellId IS NOT NULL
AND sub.BestellId <> ''
AND sub.BestellId <> 'leer'
AND sub.ServiceGroup <> 'Aktion PO'
AND DATE(sub.ServiceExpiry) > CURDATE()
"""

QUERY_LINKED = """
SELECT
sub.SubscriptionId as subscriptionid,
sub.StartDate as startdate,
sub.ServiceExpiry as serviceexpiry,
sub.BestellId as bestellid,
substr(sub.payer,-9) as accountid
FROM dbm_lesermarkt.tb_subscriptionsreport_shortened sub
WHERE sub.SubscriptionStatusID = 10
AND sub.subscribedprice > 0
AND sub.BestellId IS NOT NULL
AND sub.BestellId <> ''
AND sub.BestellId <> 'leer'
AND sub.ServiceGroup <> 'Aktion PO'
AND DATE(sub.StartDate) > CURDATE()
"""

logger = logging.getLogger(__name__)


@dataclass
class UpdateSummary:
    """Zählt erfolgreiche und fehlgeschlagene API-Updates."""

    successful_updates: int = 0
    failed_updates: int = 0


@dataclass
class UpdateResult:
    """Bündelt Zähler und Detailzeilen erfolgreicher API-Updates."""

    summary: UpdateSummary
    successful_updates: pd.DataFrame


def is_in_window(ts: pd.Timestamp) -> bool:
    """
    Prüft, ob ein Zeitstempel im zulässigen Verschiebungsfenster liegt.
    """
    timestamp = pd.Timestamp(ts)
    return bool(not is_special_early_renewal(timestamp))


def is_special_early_renewal(ts: pd.Timestamp) -> bool:
    """
    Prueft, ob ein Renewal unter die Sonderregel fuer den 22. vor 08:00 Uhr faellt.
    """
    timestamp = pd.Timestamp(ts)
    return bool(timestamp.day == SPECIAL_DAY_OF_MONTH and timestamp.time() < SPECIAL_SOURCE_END_TIME)


def is_on_ten_second_step(ts: pd.Timestamp) -> bool:
    """
    Prüft, ob ein Zeitstempel exakt auf einem 10-Sekunden-Schritt liegt.
    """
    return bool(ts.second % STEP_SECONDS == 0 and ts.microsecond == 0)


def get_slot_capacity(ts: pd.Timestamp | datetime) -> int:
    """
    Ermittelt die maximale Slot-Kapazitaet fuer einen Zielzeitpunkt.
    """
    timestamp_time = pd.Timestamp(ts).time()
    if DAYTIME_START_TIME <= timestamp_time < DAYTIME_END_TIME:
        return DAYTIME_MAX_PER_TIMESTAMP
    return NIGHTTIME_MAX_PER_TIMESTAMP


def get_allowed_slot_window(original_ts: pd.Timestamp) -> tuple[datetime_time, datetime_time]:
    """
    Ermittelt das erlaubte Zielzeitfenster fuer den Originalzeitpunkt.
    """
    if is_special_early_renewal(original_ts):
        return SPECIAL_TARGET_START_TIME, SPECIAL_TARGET_END_TIME
    return FULL_DAY_START_TIME, FULL_DAY_END_TIME


def build_window_end(day: date, start_time: datetime_time, end_time: datetime_time) -> datetime:
    """
    Baut den exklusiven Endzeitpunkt eines Tagesfensters.
    """
    end_day = day
    if end_time <= start_time:
        end_day += timedelta(days=1)
    return datetime.combine(end_day, end_time)


def generate_time_slots_for_day(
    day: date,
    start_time: datetime_time = FULL_DAY_START_TIME,
    end_time: datetime_time = FULL_DAY_END_TIME,
) -> list[datetime]:
    """
    Erzeugt alle zulässigen 10-Sekunden-Slots für einen Kalendertag.
    """
    start_dt = datetime.combine(day, start_time)
    end_dt = build_window_end(day, start_time, end_time)

    slots = []
    current = start_dt
    while current < end_dt:
        slots.append(current)
        current += timedelta(seconds=STEP_SECONDS)
    return slots


def build_empty_subscription_preview(df: pd.DataFrame) -> pd.DataFrame:
    """
    Erzeugt eine leere Subscription-Vorschau mit erwarteten Ausgabespalten.
    """
    preview = df.rename(columns={"serviceexpiry": "old_serviceexpiry"}).copy()
    preview["original_ts"] = pd.NaT
    preview["new_ts"] = pd.NaT
    preview["status"] = pd.Series(dtype="object")
    preview["group_size"] = pd.Series(dtype="int64")
    return preview


def find_eligible_bestellids(df: pd.DataFrame) -> tuple[pd.Series, pd.DataFrame]:
    """
    Ermittelt verschiebbare BestellIds und Gruppen mit mehreren ServiceExpiry-Werten.
    """
    grouped_window = (
        df.groupby("bestellid")["serviceexpiry"]
        .agg(
            min="min",
            max="max",
            distinct_ts_count="nunique",
            is_ten_second_step=lambda values: values.apply(is_on_ten_second_step).all(),
        )
        .reset_index()
    )

    multiple_serviceexpiry_groups = grouped_window[grouped_window["distinct_ts_count"] > 1].copy()
    eligible_ids = grouped_window[grouped_window["is_ten_second_step"] & (grouped_window["distinct_ts_count"] == 1)][
        "bestellid"
    ]
    return eligible_ids, multiple_serviceexpiry_groups


def count_linked_subscriptions(linked_df: pd.DataFrame) -> pd.DataFrame:
    """
    Zaehlt verknuepfte Status-10-Abos pro BestellId fuer die Slot-Kapazitaet.
    """
    if linked_df.empty or "bestellid" not in linked_df.columns:
        return pd.DataFrame(columns=["bestellid", "linked_group_size"])

    linked = linked_df.copy()
    linked["bestellid"] = linked["bestellid"].astype(str).str.strip()
    return linked.groupby("bestellid").size().reset_index(name="linked_group_size")


def build_group_info(df: pd.DataFrame, linked_df: pd.DataFrame | None = None) -> pd.DataFrame:
    """
    Verdichtet Subscription-Daten auf BestellId-Ebene.
    """
    group_info = (
        df.groupby("bestellid")
        .agg(
            group_size=("subscriptionid", "count"),
            original_ts=("serviceexpiry", "min"),
            distinct_ts_count=("serviceexpiry", "nunique"),
        )
        .reset_index()
    )
    if linked_df is None:
        group_info["linked_group_size"] = 0
    else:
        linked_counts = count_linked_subscriptions(linked_df)
        group_info = group_info.merge(linked_counts, on="bestellid", how="left")
        group_info["linked_group_size"] = group_info["linked_group_size"].fillna(0).astype("int64")
    group_info["slot_load"] = group_info["group_size"] + group_info["linked_group_size"]

    group_info["original_day"] = group_info["original_ts"].dt.date
    group_info["new_ts"] = pd.NaT
    group_info["status"] = None
    return group_info


def is_allowed_target_slot(original_ts: pd.Timestamp, target_ts: pd.Timestamp) -> bool:
    """
    Prueft, ob ein Zielzeitpunkt zum Originalzeitpunkt passt.
    """
    original_timestamp = pd.Timestamp(original_ts)
    target_timestamp = pd.Timestamp(target_ts)
    if target_timestamp.date() != original_timestamp.date():
        return False

    start_time, end_time = get_allowed_slot_window(original_timestamp)
    window_start = datetime.combine(original_timestamp.date(), start_time)
    window_end = build_window_end(original_timestamp.date(), start_time, end_time)
    return bool(window_start <= target_timestamp.to_pydatetime() < window_end)


def mark_groups_for_assignment(group_info: pd.DataFrame) -> tuple[pd.DataFrame, pd.DataFrame]:
    """
    Trennt zu große Gruppen ab und markiert übrige Gruppen für STAY oder MOVE.
    """
    group_info = group_info.copy()
    too_large_mask = group_info["slot_load"] > NIGHTTIME_MAX_PER_TIMESTAMP
    group_info.loc[too_large_mask, "status"] = "TOO_LARGE"
    group_info.loc[too_large_mask, "new_ts"] = group_info.loc[too_large_mask, "original_ts"]

    assignable = group_info[~too_large_mask].copy()
    too_large_groups = group_info[too_large_mask].copy()
    if assignable.empty:
        return assignable, too_large_groups

    assignable = assignable.sort_values(
        ["original_ts", "slot_load", "bestellid"],
        ascending=[True, False, True],
    )
    assignable["running_size"] = assignable.groupby("original_ts")["slot_load"].cumsum()
    assignable["can_stay"] = assignable.apply(
        lambda row: (
            row["running_size"] <= get_slot_capacity(row["original_ts"])
            and is_allowed_target_slot(row["original_ts"], row["original_ts"])
        ),
        axis=1,
    )
    assignable["status"] = assignable["can_stay"].apply(lambda can_stay: "STAY" if can_stay else "MOVE")
    assignable["new_ts"] = assignable.apply(
        lambda row: row["original_ts"] if row["status"] == "STAY" else pd.NaT,
        axis=1,
    )
    assignable = assignable.drop(columns=["can_stay"])
    return assignable, too_large_groups


def collect_slot_usage(day_groups: pd.DataFrame) -> dict[datetime, int]:
    """
    Ermittelt die bereits belegte Slot-Kapazität eines Tages.
    """
    slot_usage: dict[datetime, int] = {}
    stays = day_groups[day_groups["status"] == "STAY"].copy()
    for _, row in stays.iterrows():
        ts = row["original_ts"].to_pydatetime()
        slot_usage[ts] = slot_usage.get(ts, 0) + int(row["slot_load"])
    return slot_usage


def find_assignable_slot(
    day: date,
    original_ts: pd.Timestamp,
    needed: int,
    slot_usage: dict[datetime, int],
) -> datetime | None:
    """
    Sucht einen bestehenden oder freien Zeitslot mit ausreichender Restkapazität.
    """
    start_time, end_time = get_allowed_slot_window(original_ts)
    original_dt = pd.Timestamp(original_ts).to_pydatetime()
    slots = sorted(
        generate_time_slots_for_day(day, start_time, end_time),
        key=lambda slot: (abs(slot - original_dt), slot),
    )

    for ts in slots:
        used = slot_usage.get(ts, 0)
        if used + needed <= get_slot_capacity(pd.Timestamp(ts)):
            return ts

    return None


def assign_day_groups(day: date, day_groups: pd.DataFrame) -> pd.DataFrame:
    """
    Verteilt MOVE-Gruppen eines Tages auf verfügbare 10-Sekunden-Slots.
    """
    day_groups = day_groups.copy()
    slot_usage = collect_slot_usage(day_groups)
    moves = day_groups[day_groups["status"] == "MOVE"].copy()
    moves = moves.sort_values(
        ["slot_load", "original_ts", "bestellid"],
        ascending=[False, True, True],
    )

    for idx, row in moves.iterrows():
        needed = int(row["slot_load"])
        assigned = find_assignable_slot(day, pd.Timestamp(row["original_ts"]), needed, slot_usage)
        if assigned is None:
            day_groups.at[idx, "status"] = "UNASSIGNED"
            continue

        slot_usage[assigned] = slot_usage.get(assigned, 0) + needed
        assigned_ts = pd.Timestamp(assigned)
        day_groups.at[idx, "new_ts"] = assigned_ts
        day_groups.at[idx, "status"] = "MOVED" if assigned_ts != row["original_ts"] else "STAY"

    return day_groups


def assign_new_timestamps(assignable: pd.DataFrame, group_info: pd.DataFrame) -> pd.DataFrame:
    """
    Plant neue Zeitpunkte für alle zuweisbaren Gruppen.
    """
    result_groups = []
    for day, day_groups in assignable.groupby("original_day"):
        result_groups.append(assign_day_groups(day, day_groups))

    if result_groups:
        assigned_groups = pd.concat(result_groups, ignore_index=True)
    else:
        assigned_groups = group_info[group_info["slot_load"] <= NIGHTTIME_MAX_PER_TIMESTAMP].copy()

    assigned_groups.loc[
        (assigned_groups["status"] == "STAY") & (assigned_groups["new_ts"].isna()),
        "new_ts",
    ] = assigned_groups["original_ts"]
    return assigned_groups


def build_preview(
    df: pd.DataFrame,
    linked_df: pd.DataFrame | None = None,
) -> tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame, pd.DataFrame]:
    """
    Plant neue ServiceExpiry-Zeitpunkte pro BestellId.
    """
    df = df.copy()
    df["bestellid"] = df["bestellid"].astype(str).str.strip()
    df["serviceexpiry"] = pd.to_datetime(df["serviceexpiry"])

    eligible_ids, multiple_serviceexpiry_groups = find_eligible_bestellids(df)
    df = df[df["bestellid"].isin(eligible_ids)].copy()
    if df.empty:
        empty_groups = pd.DataFrame(
            columns=[
                "bestellid",
                "group_size",
                "linked_group_size",
                "slot_load",
                "original_ts",
                "distinct_ts_count",
                "original_day",
                "new_ts",
                "status",
            ]
        )
        empty_subscription = build_empty_subscription_preview(df)
        return empty_groups, empty_subscription, empty_groups.copy(), multiple_serviceexpiry_groups

    group_info = build_group_info(df, linked_df)
    assignable, too_large_groups = mark_groups_for_assignment(group_info)
    final_groups = assign_new_timestamps(assignable, group_info)
    if not too_large_groups.empty:
        final_groups = pd.concat([final_groups, too_large_groups], ignore_index=True)

    preview_subscription = df.merge(
        final_groups[["bestellid", "original_ts", "new_ts", "status", "group_size", "linked_group_size", "slot_load"]],
        on="bestellid",
        how="left",
    )
    preview_subscription = preview_subscription.rename(columns={"serviceexpiry": "old_serviceexpiry"})
    preview_bestellid = final_groups.sort_values(["original_day", "original_ts", "bestellid"]).reset_index(drop=True)
    return preview_bestellid, preview_subscription, too_large_groups, multiple_serviceexpiry_groups


def combine_date_with_time(date_source: pd.Timestamp, time_source: pd.Timestamp) -> pd.Timestamp:
    """
    Kombiniert das Datum des bestehenden StartDate mit der Uhrzeit des geplanten Basis-Zeitpunkts.
    """
    source_date = pd.Timestamp(date_source).date()
    source_time = pd.Timestamp(time_source).time()
    return pd.Timestamp(datetime.combine(source_date, source_time))


def build_startdate_preview(preview_bestellid: pd.DataFrame, linked_df: pd.DataFrame) -> pd.DataFrame:
    """
    Erzeugt die StartDate-Vorschau für verknüpfte Status-10-Abos.
    """
    required_columns = {"subscriptionid", "bestellid", "startdate"}
    missing_columns = required_columns - set(linked_df.columns)
    if missing_columns:
        missing_columns_text = ", ".join(sorted(missing_columns))
        raise ValueError(f"linked_df enthält nicht alle benötigten Spalten: {missing_columns_text}")

    if preview_bestellid.empty or linked_df.empty:
        return pd.DataFrame(
            columns=[
                "subscriptionid",
                "bestellid",
                "old_startdate",
                "new_startdate",
                "basis_serviceexpiry",
                "basis_status",
            ]
        )

    linked_df = linked_df.copy()
    linked_df["bestellid"] = linked_df["bestellid"].astype(str).str.strip()
    basis_timestamps = preview_bestellid[
        preview_bestellid["new_ts"].notna() & preview_bestellid["status"].isin(["STAY", "MOVED"])
    ][["bestellid", "original_ts", "new_ts", "status"]].copy()
    basis_timestamps["bestellid"] = basis_timestamps["bestellid"].astype(str).str.strip()

    startdate_preview = linked_df.merge(
        basis_timestamps,
        on="bestellid",
        how="inner",
    )
    startdate_preview["new_startdate"] = startdate_preview.apply(
        lambda row: combine_date_with_time(row["startdate"], row["new_ts"]),
        axis=1,
    )
    return startdate_preview.rename(
        columns={
            "startdate": "old_startdate",
            "original_ts": "basis_serviceexpiry",
            "status": "basis_status",
        }
    )


def load_source_data() -> tuple[pd.DataFrame, pd.DataFrame]:
    """
    Lädt Basis-Abos und verknüpfte Abos aus der Datenbank.
    """
    service_expiry_df = execute_sql_query(QUERY_SERVICE_EXPIRY)
    linked_df = execute_sql_query(QUERY_LINKED)
    return service_expiry_df, linked_df


def build_moved_previews(service_expiry_df: pd.DataFrame, linked_df: pd.DataFrame) -> tuple[pd.DataFrame, pd.DataFrame]:
    """
    Erstellt die auf tatsächlich verschobene Datensätze reduzierten Vorschauen.
    """
    preview_bestellid, preview_subscription, *_ = build_preview(service_expiry_df, linked_df)
    startdate_preview = build_startdate_preview(preview_bestellid, linked_df)
    moved_subscription_preview = preview_subscription[preview_subscription["status"] == "MOVED"].copy()
    moved_startdate_preview = startdate_preview[startdate_preview["basis_status"] == "MOVED"].copy()
    return moved_subscription_preview, moved_startdate_preview


def build_out_of_window_preview(preview_subscription: pd.DataFrame) -> pd.DataFrame:
    """
    Erstellt eine Dry-Run-Vorschau fuer Basis-Abos ohne zulaessigen Zielzeitpunkt.
    """
    output_columns = [
        "update_field",
        "accountid",
        "subscriptionid",
        "bestellid",
        "old_value",
        "new_value",
        "group_size",
    ]
    if preview_subscription.empty:
        return pd.DataFrame(columns=output_columns)

    preview = preview_subscription[preview_subscription["status"].isin(["UNASSIGNED", "TOO_LARGE"])].copy()
    if preview.empty:
        return pd.DataFrame(columns=output_columns)

    preview["update_field"] = "OutOfWindow"
    preview["old_value"] = preview["old_serviceexpiry"]
    preview["new_value"] = preview["new_ts"]
    return preview.reindex(columns=output_columns).reset_index(drop=True)


def format_api_timestamp(ts: pd.Timestamp) -> str:
    """
    Formatiert einen lokalen Zeitstempel für die REST-API in UTC.
    """
    local_ts = pd.Timestamp(ts).tz_localize(LOCAL_TIMEZONE, ambiguous=False, nonexistent="shift_forward")
    return str(local_ts.tz_convert("UTC").strftime("%Y-%m-%dT%H:%M:%SZ"))


def send_subscription_patch(accountid: str, subscriptionid: str, data: list[dict[str, str]]) -> bool:
    """
    Sendet einen PATCH-Aufruf für eine Subscription und meldet den Erfolg zurück.
    """
    api_config = get_esuite_api_config("PROD")
    url = api_config.resthost + "accounts/" + accountid + "/subscriptions/" + subscriptionid
    paths = ", ".join(item["path"] for item in data)
    logger.debug(
        "Sende Renewal-Verschiebung für Account %s, Subscription %s, Felder: %s",
        accountid,
        subscriptionid,
        paths,
    )
    time.sleep(API_DELAY_SECONDS)

    try:
        response = retry_request("PATCH", url, data=json.dumps(data), headers=api_config.headers, verify=False)
    except requests.exceptions.RequestException as exc:
        logger.error(
            "Renewal-Verschiebung fehlgeschlagen für Account %s, Subscription %s: %s",
            accountid,
            subscriptionid,
            exc,
            exc_info=True,
        )
        return False

    if response is not None and response.status_code == 200:
        logger.debug(
            "Renewal-Verschiebung erfolgreich für Account %s, Subscription %s",
            accountid,
            subscriptionid,
        )
        return True

    status = response.status_code if response is not None else "Keine Antwort"
    text = response.text if response is not None else ""
    logger.warning(
        "Fehler bei Renewal-Verschiebung für Account %s, Subscription %s: %s - %s",
        accountid,
        subscriptionid,
        status,
        text,
    )
    return False


def apply_expiry_updates(preview_subscription: pd.DataFrame) -> UpdateResult:
    """
    Aktualisiert das ExpiryDate für verschobene Basis-Abos.
    """
    summary = UpdateSummary()
    successful_rows: list[dict[str, object]] = []
    for _, row in iter_with_progress(
        logger,
        preview_subscription.iterrows(),
        len(preview_subscription),
        "ExpiryDate-Updates",
    ):
        accountid = str(row["accountid"])
        subscriptionid = str(row["subscriptionid"])
        old_expiry = pd.Timestamp(row["old_serviceexpiry"])
        new_expiry = pd.Timestamp(row["new_ts"])
        new_expiry_basis = format_api_timestamp(new_expiry)
        data = [{"op": "replace", "path": "/ExpiryDate", "value": new_expiry_basis}]

        if send_subscription_patch(accountid, subscriptionid, data):
            summary.successful_updates += 1
            successful_rows.append(
                {
                    "accountid": accountid,
                    "subscriptionid": subscriptionid,
                    "olddate": old_expiry,
                    "newdate": new_expiry,
                }
            )
        else:
            summary.failed_updates += 1
    logger.info(
        "ExpiryDate-Updates abgeschlossen: %s erfolgreich, %s fehlgeschlagen.",
        summary.successful_updates,
        summary.failed_updates,
    )
    return UpdateResult(summary, pd.DataFrame(successful_rows))


def apply_startdate_updates(startdate_preview: pd.DataFrame) -> UpdateResult:
    """
    Aktualisiert das StartDate für verknüpfte Abos.
    """
    summary = UpdateSummary()
    successful_rows: list[dict[str, object]] = []
    for _, row in iter_with_progress(
        logger,
        startdate_preview.iterrows(),
        len(startdate_preview),
        "StartDate-Updates",
    ):
        accountid = str(row["accountid"])
        subscriptionid = str(row["subscriptionid"])
        old_start = pd.Timestamp(row["old_startdate"])
        new_start = pd.Timestamp(row["new_startdate"])
        new_start_basis = format_api_timestamp(new_start)
        data = [{"op": "replace", "path": "/StartDate", "value": new_start_basis}]

        if send_subscription_patch(accountid, subscriptionid, data):
            summary.successful_updates += 1
            successful_rows.append(
                {
                    "accountid": accountid,
                    "subscriptionid": subscriptionid,
                    "olddate": old_start,
                    "newdate": new_start,
                }
            )
        else:
            summary.failed_updates += 1
    logger.info(
        "StartDate-Updates abgeschlossen: %s erfolgreich, %s fehlgeschlagen.",
        summary.successful_updates,
        summary.failed_updates,
    )
    return UpdateResult(summary, pd.DataFrame(successful_rows))


def merge_summaries(*summaries: UpdateSummary) -> UpdateSummary:
    """
    Fasst mehrere Update-Zähler zu einem Gesamtergebnis zusammen.
    """
    total = UpdateSummary()
    for summary in summaries:
        total.successful_updates += summary.successful_updates
        total.failed_updates += summary.failed_updates
    return total


def merge_successful_updates(*update_results: UpdateResult) -> pd.DataFrame:
    """
    Fasst Detailzeilen erfolgreicher Updates zu einem Ausgabe-DataFrame zusammen.
    """
    output_columns = ["accountid", "subscriptionid", "olddate", "newdate"]
    frames = [result.successful_updates for result in update_results if not result.successful_updates.empty]
    if not frames:
        return pd.DataFrame(columns=output_columns)

    return pd.concat(frames, ignore_index=True).reindex(columns=output_columns)


def build_result_dataframe(status: str, summary: UpdateSummary, total_to_update: int, now: datetime) -> pd.DataFrame:
    """
    Baut das SQLMesh-kompatible Ergebnis des Verschiebungslaufs.
    """
    return pd.DataFrame(
        [
            {
                "status": status,
                "successful_updates": summary.successful_updates,
                "failed_updates": summary.failed_updates,
                "total_to_update": total_to_update,
                "execution_time": now,
                "execution_id": int(now.timestamp()),
            }
        ]
    )


def execute_renewal_shift_previews(
    preview_subscription: pd.DataFrame,
    startdate_preview: pd.DataFrame,
    status: str,
    return_successful_updates: bool = False,
) -> pd.DataFrame:
    """
    Führt API-Updates für vorbereitete Preview-DataFrames aus.
    """
    now = datetime.now()
    total_to_update = len(preview_subscription) + len(startdate_preview)
    logger.info(
        "%s: %s ExpiryDate-Updates und %s StartDate-Updates geplant.",
        status,
        len(preview_subscription),
        len(startdate_preview),
    )

    if total_to_update == 0:
        logger.info("Keine Subscriptions zur Verschiebung gefunden.")
        if return_successful_updates:
            return merge_successful_updates()
        return build_result_dataframe("keine Einträge", UpdateSummary(), total_to_update, now)

    expiry_result = apply_expiry_updates(preview_subscription)
    startdate_result = apply_startdate_updates(startdate_preview)
    summary = merge_summaries(expiry_result.summary, startdate_result.summary)
    logger.info(
        "%s: %s von %s Updates erfolgreich, %s fehlgeschlagen.",
        status,
        summary.successful_updates,
        total_to_update,
        summary.failed_updates,
    )
    if return_successful_updates:
        return merge_successful_updates(expiry_result, startdate_result)
    return build_result_dataframe(status, summary, total_to_update, now)


def run_renewal_shift_api_test(return_successful_updates: bool = False) -> pd.DataFrame:
    """
    Testet jeweils den ersten API-Update aus der Expiry- und StartDate-Preview.
    """
    service_expiry_df, linked_df = load_source_data()
    preview_subscription, startdate_preview = build_moved_previews(service_expiry_df, linked_df)
    test_preview_subscription = preview_subscription.head(1).copy()
    test_startdate_preview = startdate_preview.head(1).copy()
    logger.info(
        "API-Testlauf vorbereitet: 1 von %s ExpiryDate-Kandidaten und 1 von %s StartDate-Kandidaten werden getestet.",
        len(preview_subscription),
        len(startdate_preview),
    )
    return execute_renewal_shift_previews(
        test_preview_subscription,
        test_startdate_preview,
        "API-Test abgeschlossen",
        return_successful_updates=return_successful_updates,
    )


def run_renewal_shift_dry_run() -> pd.DataFrame:
    """
    Erstellt eine Vorschau der tatsächlich anzupassenden Renewal-Datensätze.
    """
    service_expiry_df, linked_df = load_source_data()
    preview_bestellid, preview_subscription, *_ = build_preview(service_expiry_df, linked_df)
    startdate_preview = build_startdate_preview(preview_bestellid, linked_df)
    out_of_window_preview = build_out_of_window_preview(preview_subscription)
    preview_subscription = preview_subscription[preview_subscription["status"] == "MOVED"].copy()
    startdate_preview = startdate_preview[startdate_preview["basis_status"] == "MOVED"].copy()
    output_columns = [
        "update_field",
        "accountid",
        "subscriptionid",
        "bestellid",
        "old_value",
        "new_value",
        "group_size",
    ]

    expiry_preview = preview_subscription.assign(update_field="ExpiryDate").rename(
        columns={
            "old_serviceexpiry": "old_value",
            "new_ts": "new_value",
        }
    )
    expiry_preview = expiry_preview.reindex(columns=output_columns)

    startdate_preview = startdate_preview.assign(update_field="StartDate").rename(
        columns={
            "old_startdate": "old_value",
            "new_startdate": "new_value",
        }
    )
    startdate_preview["group_size"] = pd.NA
    startdate_preview = startdate_preview.reindex(columns=output_columns)

    return pd.concat([expiry_preview, startdate_preview, out_of_window_preview], ignore_index=True)


def run_renewal_shift(return_successful_updates: bool = False) -> pd.DataFrame:
    """
    Führt den kompletten manuellen Renewal-Verschiebungslauf aus.
    """
    service_expiry_df, linked_df = load_source_data()
    preview_subscription, startdate_preview = build_moved_previews(service_expiry_df, linked_df)
    return execute_renewal_shift_previews(
        preview_subscription,
        startdate_preview,
        "Verschiebung abgeschlossen",
        return_successful_updates=return_successful_updates,
    )
